      const rec={s:st&&st!=="?"?st:(i?"P":""),in:i||null,out:null,in2:null,out2:null,ot:asNum(r.ot)?asNum(r.ot):null,st:asTime(r.st)||null,note:str(r.note)||null,sh:null,auto:null};
