  fields:[F("name","Ledger",/ledger|name|account|party/,1),F("kind","Type",/type|kind|group/),F("dr","Debit",/debit|dr\b/),F("cr","Credit",/credit|cr\b/),F("bal","Balance (+Dr / −Cr)",/balance|amount|opening/),F("side","Dr / Cr",/dr\s*\/\s*cr|side/),F("phone","Phone",/phone|mobile/),F("gstin","GSTIN",/gst/)],
